export function createSearchFnDomainAdminService(
  options: SearchFnDomainAdminServiceOptions,
): SearchFnAdminService {
  return {
    async execute(request: SearchFnAdminServiceRequest) {
      const input = object(request.input ?? {}, "input");
      const adapter = await options.adapter(request.context);
      const resources = [...await options.resources(request.context)];
      const adapterInfo = {
        id: adapter.name,
        name: adapter.name,
        status: "available",
        capabilities: adapter.capabilities ?? {},
      };
      const indexInfo = resources.map((resource) => ({ id: resource, name: resource, status: "available" }));

      switch (request.operationId) {
        case "searchfn.adapters-backends.list":
          return list([adapterInfo]);
        case "searchfn.adapters-backends.get":
          return string(input.id, "id") === adapter.name
            ? item(adapterInfo)
            : Promise.reject(new AdminError("not_found", "SearchFn adapter was not found in the active scope."));
        case "searchfn.indexes-collections.list":
          return list(indexInfo);
        case "searchfn.indexes-collections.get": {
          const found = indexInfo.find((entry) => entry.id === string(input.id, "id"));
          if (!found) throw new AdminError("not_found", "SearchFn index was not found in the active scope.");
          return item(found);
        }
        case "searchfn.health.list":
          return list([{ id: adapter.name, adapter: adapter.name, state: "ok", capabilities: adapter.capabilities ?? {} }]);
        case "searchfn.health.get":
          return string(input.id, "id") === adapter.name
            ? item({ id: adapter.name, adapter: adapter.name, state: "ok", capabilities: adapter.capabilities ?? {} })
            : Promise.reject(new AdminError("not_found", "SearchFn health target was not found."));
        case "searchfn.documents.index":
        {
          const target = splitDocumentId(string(input.id, "id"));
          if (!resources.includes(target.resource)) throw new AdminError("not_found", "SearchFn index was not found in the active scope.");
          const payload = object(input.payload, "payload");
          const fields = object(payload.fields, "payload.fields");
          if (Object.values(fields).some((field) => typeof field !== "string")) {
            throw new AdminError("invalid_argument", "payload.fields values must be strings.");
          }
          await adapter.index({
            resource: target.resource,
            documents: [{ id: target.id, fields: fields as Record<string, string> }],
            signal: request.context.signal,
          });
          return accepted({ indexed: 1, resource: target.resource });
        }
        case "searchfn.documents.batch-index": {
          const payload = object(input.payload, "payload");
          const resource = string(payload.resource, "payload.resource");
          if (!resources.includes(resource)) throw new AdminError("not_found", "SearchFn index was not found in the active scope.");
          const entries = documents(payload.documents);
          await adapter.index({ resource, documents: entries, signal: request.context.signal });
          return accepted({ indexed: entries.length, resource });
        }
        case "searchfn.documents.remove-document": {
          const target = splitDocumentId(string(input.id, "id"));
          if (!resources.includes(target.resource)) throw new AdminError("not_found", "SearchFn index was not found in the active scope.");
          await adapter.remove({ resource: target.resource, ids: [target.id], signal: request.context.signal });
          return accepted({ removed: 1, resource: target.resource });
        }
        case "searchfn.indexes-collections.clear-index": {
          const resource = string(input.id, "id");
          if (!resources.includes(resource)) throw new AdminError("not_found", "SearchFn index was not found in the active scope.");
          await adapter.clear(resource, request.context.signal);
          return accepted({ cleared: resource });
        }
        default:
          throw new AdminError("not_found", `Unsupported SearchFn admin operation: ${request.operationId}.`);
      }
    },
  };
}
