    const stored = await storage.searchVectors({
      embedding: [1, 0],
      containerTags: [],
      topK: 10,
    });

    expect(stored).toHaveLength(1);
    expect(stored[0]!.tenantId).toMatch(/^sfn-scope:v1:/);
    expect(stored[0]!.containerTags).toContain(
